"import json
import os
import sys

sys.stdout.reconfigure(encoding='utf-8')

with open('assets/data/scriptures_index.json', encoding='utf-8') as f:
    idx = json.load(f)

print("=== SCRIPTURE TRANSLATION PROGRESS ===", flush=True)

# Check specifically Bhagavata Skandhas & Shiva Purana & Upanishads
categories = {}
for s in idx:
    sid = s.get('id', '')
    title = s.get('title', '')
    ch_list = s.get('chapters', [])
    if not ch_list:
        continue

    translated = 0
    total = len(ch_list)
    for c in ch_list:
        fname = os.path.join('assets', 'data', 'chapters', f"{c['id']}.txt")
        if os.path.exists(fname):
            try:
                # Read just the first 1KB to check quickly
                with open(fname, 'r', encoding='utf-8') as cf:
                    head = cf.read(1000)
                    if 'ಶಬ್ದಾರ್ಥ:' in head:
                        translated += 1
            except Exception:
                pass

    cat = sid.split('_')[0] if '_' in sid else 'other'
    if cat not in categories:
        categories[cat] = []
    categories[cat].append((sid, title, translated, total))

for cat, items in categories.items():
    print(f"\n--- Category: {cat} ---", flush=True)
    for sid, title, trans, tot in items:
        if trans > 0 or tot <= 50:
            status = "DONE" if trans == tot and tot > 0 else f"{trans}/{tot}"
            print(f"[{status}] {sid}: {title}", flush=True)
