def check_scripture(s):
    sid = s.get('id', '')
    title = s.get('title', '')
    ch_list = s.get('chapters', [])
    if not ch_list:
        return
    translated = 0
    total = len(ch_list)
    for c in ch_list:
        fname = os.path.join('assets', 'data', 'chapters', f"{c['id']}.txt")
        if os.path.exists(fname):
            try:
                with open(fname, 'r', encoding='utf-8') as cf:
                    head = cf.read(1500)
                    if 'ಶಬ್ದಾರ್ಥ:' in head:
                        translated += 1
            except Exception:
                pass
    status = "COMPLETED" if (translated == total and total > 0) else f"{translated}/{total}"
    print(f"[{status:^10}] {sid:35} | {title}", flush=True)

print("--- BHAGAVATA PURANA SKANDHAS ---", flush=True)
for s in idx:
    if 'purana_bhagavata_' in s.get('id', ''):
        check_scripture(s)

print("\n--- SHIVA PURANA SAMHITAS ---", flush=True)
for s in idx:
    if 'purana_shiva_' in s.get('id', ''):
        check_scripture(s)

print("\n--- DEVI BHAGAVATA ---", flush=True)
for s in idx:
    if 'purana_devi_bhagavata_' in s.get('id', ''):
        check_scripture(s)

